import React, { useState, useEffect, Fragment } from "react";
import { Dialog, Disclosure, Transition } from "@headlessui/react";
import { GatsbyImage, getImage } from "gatsby-plugin-image";
import { graphql, useStaticQuery } from "gatsby";
import { PiCaretLeftBold, PiCaretRightBold } from "react-icons/pi";
import { LiaWindowCloseSolid } from "react-icons/lia";
import { PiCaretDownThin } from "react-icons/pi";
import { useTranslation } from "gatsby-plugin-react-i18next";


type ImageNode = {
  name: string;
  relativeDirectory: string;
  childImageSharp?: {
    gatsbyImageData: import("gatsby-plugin-image").IGatsbyImageData;
  };
};

const GalleryAccordionModal = () => {
  const data: {
    allFile: {
      nodes: ImageNode[];
    };
  } = useStaticQuery(graphql`
    query GalleryImagesByDirectory {
      allFile(
        filter: {
          sourceInstanceName: { eq: "gallery" }
          extension: { regex: "/(jpg|jpeg|png)/" }
        }
      ) {
        nodes {
          name
          relativeDirectory
          childImageSharp {
            gatsbyImageData(width: 600, height: 600, placeholder: BLURRED)
          }
        }
      }
    }
  `);

  // Agrupamos imágenes por categoría y carpeta
  const imagesByFolder: Record<string, Record<string, ImageNode[]>> = {};

  data.allFile.nodes.forEach((node) => {
    const [category, folder] = node.relativeDirectory.split("/");
    if (!imagesByFolder[category]) imagesByFolder[category] = {};
    if (!imagesByFolder[category][folder]) imagesByFolder[category][folder] = [];
    imagesByFolder[category][folder].push(node);
  });

  const [selectedFolderImages, setSelectedFolderImages] = useState<ImageNode[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [autoplay, setAutoplay] = useState(true);
  const { t } = useTranslation();

  useEffect(() => {
    let interval: NodeJS.Timeout;
    if (isModalOpen && autoplay && selectedFolderImages.length > 1) {
      interval = setInterval(() => {
        setCurrentIndex((prev) => (prev + 1) % selectedFolderImages.length);
      }, 4000);
    }
    return () => clearInterval(interval);
  }, [isModalOpen, autoplay, selectedFolderImages]);

  const openGallery = (images: ImageNode[]) => {
    setSelectedFolderImages(images);
    setCurrentIndex(0);
    setIsModalOpen(true);
    setAutoplay(true);
  };

  const closeGallery = () => {
    setIsModalOpen(false);
    setSelectedFolderImages([]);
    setAutoplay(false);
  };

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev === 0 ? selectedFolderImages.length - 1 : prev - 1));
    setAutoplay(false);
  };

  const handleNext = () => {
    setCurrentIndex((prev) => (prev + 1) % selectedFolderImages.length);
    setAutoplay(false);
  };

  return (
    <section className="max-w-6xl mx-auto px-4 py-8 w-full">
      <h2 className="text-3xl font-bold text-accent mb-6 text-center">{t("menu.projects")}</h2>
      <div className="space-y-4 w-full">
        {Object.entries(imagesByFolder).map(([category, folders]) => (
          <Disclosure key={category}>
            {({ open }) => (
              <div className="border shadow bg-white w-full">
                <Disclosure.Button className="w-full text-left px-4 py-3 font-semibold bg-gray-100 text-gray-700 hover:bg-gray-200 flex flex-row justify-between items-center">
                  <span>{category.charAt(0).toUpperCase() + category.slice(1)}</span>
                  <PiCaretDownThin
                    className={`w-6 h-6 transform transition-transform duration-300 ${open ? "rotate-180" : "rotate-0"}`}
                  />
                </Disclosure.Button>
                <Disclosure.Panel className="p-4 grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
                  {Object.entries(folders).map(([folder, images]) => {
                    const firstImageData = getImage(images[0].childImageSharp ?? null);
                    return (
                      <div
                        key={folder}
                        className="cursor-pointer text-center"
                        onClick={() => openGallery(images)}
                      >
                        {firstImageData ? (
                          <GatsbyImage
                            image={firstImageData}
                            alt={folder}
                            className="rounded shadow hover:scale-105 transition"
                          />
                        ) : (
                          <div className="w-[600px] h-[600px] bg-gray-200 flex items-center justify-center rounded">
                            <span className="text-gray-500">Image not available</span>
                          </div>
                        )}
                        <p className="mt-2 text-sm font-semibold text-gray-800 uppercase">{folder}</p>
                      </div>
                    );
                  })}
                </Disclosure.Panel>
              </div>
            )}
          </Disclosure>
        ))}
      </div>

      <Transition appear show={isModalOpen} as={Fragment}>
        <Dialog as="div" className="relative z-50" onClose={closeGallery}>
          <div className="fixed inset-0 bg-black bg-opacity-70" aria-hidden="true" />
          <div className="fixed inset-0 flex items-center justify-center">
            <div className="bg-white rounded w-full sm:w-[700px] h-full sm:h-[700px] relative top-10 bottom-8">
              <button
                onClick={closeGallery}
                className="absolute -top-10 right-0 text-accent text-3xl z-[55]"
              >
                <LiaWindowCloseSolid className="text-5xl text-gray-200" />
              </button>

              {selectedFolderImages.length > 0 && (
                <>
                  <div className="relative flex items-center justify-center">
                    <button
                      onClick={handlePrev}
                      className="absolute left-0 top-1/2 transform -translate-y-1/2 hover:bg-white/30 px-2 py-1 z-[55]"
                      aria-label="Previous"
                    >
                      <PiCaretLeftBold className="text-6xl text-gray-200" />
                    </button>

                    {/* Renderizamos solo si imageData no es undefined */}
                    {(() => {
                      const currentImageData = getImage(selectedFolderImages[currentIndex]?.childImageSharp ?? null);
                      if (!currentImageData) {
                        return (
                          <div className="w-full h-[80vh] flex items-center justify-center bg-gray-200 rounded">
                            <span className="text-gray-500">Image not available</span>
                          </div>
                        );
                      }

                      return (
                        <GatsbyImage
                          image={currentImageData}
                          alt={selectedFolderImages[currentIndex]?.name || "Gallery image"}
                          className="w-full h-full object-contain"
                        />
                      );
                    })()}

                    <button
                      onClick={handleNext}
                      className="absolute right-0 top-1/2 transform -translate-y-1/2 hover:bg-white/30 px-2 py-1"
                      aria-label="Next"
                    >
                      <PiCaretRightBold className="text-6xl text-gray-200" />
                    </button>
                  </div>

                  {/* Nombre del subfolder */}
                  <div className="relative w-full bg-white/30 top-0 text-secondary text-shadow p-5">
                    <p className="text-xl font-semibold text-center uppercase">
                      {selectedFolderImages[currentIndex].relativeDirectory.split("/")[1]}
                    </p>
                  </div>

                  {/* Puntos indicadores */}
                  <div className="absolute bottom-8 justify-center flex space-x-2 w-full">
                    {selectedFolderImages.map((_, index) => (
                      <button
                        key={index}
                        onClick={() => {
                          setCurrentIndex(index);
                          setAutoplay(false);
                        }}
                        className={`w-3 h-3 rounded-full ${
                          index === currentIndex ? "bg-accent" : "bg-gray-300"
                        } transition`}
                        aria-label={`Go to slide ${index + 1}`}
                      />
                    ))}
                  </div>

                </>
              )}
            </div>
          </div>
        </Dialog>
      </Transition>
    </section>
  );
};

export default GalleryAccordionModal;
